// ../es-samples/samples/es2011/function-bind.js
function demoFunctionBind() {
  const moduleObj = {
    x: 42,
    getX: function() {
      return this.x;
    }
  };
  const unboundGetX = moduleObj.getX;
  const boundGetX = unboundGetX.bind(moduleObj);
  return { boundResult: boundGetX() };
}

// ../es-samples/samples/es2011/getters-and-setters.js
function demoGettersAndSetters() {
  const user = {
    firstName: "John",
    lastName: "Doe",
    get fullName() {
      return `${this.firstName} ${this.lastName}`;
    },
    set fullName(name) {
      const parts = name.split(" ");
      this.firstName = parts[0];
      this.lastName = parts[1] || "";
    }
  };
  const initial = user.fullName;
  user.fullName = "Jane Smith";
  return { initial, updated: user.fullName, firstName: user.firstName };
}

